export async function prepareProductUpdate(db: AccountDatabase, id: string, raw: unknown, actorEmail: string, freshProduct?:Product|null, freshCategory?: { name_ko: string; is_active: number }) {
  const input = updateProductSchema.parse(raw);
  const current = freshProduct===undefined?await findProduct(db, id):freshProduct;
  if (!current) return null;
  if (input.templateKeyOverride !== undefined) await assertTemplateOwnership(db, input.templateKeyOverride);
  if (current.version !== input.expectedVersion) throw new Error("product_conflict");
  const categoryId = input.categoryId ?? current.categoryId;
  const category = freshCategory ? (freshCategory.is_active || categoryId === current.categoryId ? freshCategory.name_ko : null) : await categoryName(db, categoryId, categoryId === current.categoryId);
  if (!category) throw new Error("category_not_found");
  const nameKo = normalizeText(input.nameKo ?? current.nameKo);
  const descriptionKo = normalizeText(input.descriptionKo ?? current.descriptionKo);
  const timestamp = now();
  const hash = await sourceHash({ nameKo, descriptionKo, categoryId, categoryNameKo: category });
  const statements: D1PreparedStatement[] = [
    db.prepare(`UPDATE products SET category_id = ?, name_ko = ?, name_ko_normalized = ?, description_ko = ?,
      translation_source_hash = ?, template_key_override = ?, currency_code = ?, version = version + 1, is_active = ?, updated_by = ?, updated_at = ?
      WHERE ${owner(db)} AND id = ? AND version = ?`)
      .bind(categoryId, nameKo, nameKo.toLocaleLowerCase("ko"), descriptionKo, hash,
        input.templateKeyOverride === undefined ? current.templateKeyOverride : input.templateKeyOverride,
        input.currencyCode ?? current.currencyCode, input.isActive === undefined ? (current.isActive ? 1 : 0) : (input.isActive ? 1 : 0),
        actorEmail, timestamp, id, input.expectedVersion),
  ];
  if (input.offers) {
    statements.push(db.prepare("DELETE FROM product_offers WHERE product_id = ?").bind(id));
    statements.push(...input.offers.map((offer, index) => db.prepare(`INSERT INTO product_offers
      (id, product_id, sort_order, quantity, unit_code, unit_custom_ko, price_krw, price_minor, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .bind(crypto.randomUUID(), id, index, offer.quantity, offer.unitCode, offer.unitCustomKo ?? null,
        offer.priceKrw, Math.round(offer.priceKrw * 100), timestamp, timestamp)));
  }
  return { id, statements };
}

